import pdfplumber

with pdfplumber.open('main.pdf') as pdf:
    page_info = {}

    for page_num, page in enumerate(pdf.pages):
        text = page.extract_text()
        if not text:
            continue

        # Look for major section headers at the start of pages
        first_500_chars = text[:500]

        if re.search(r'^\s*(Introduction|Related Work|Method|Experiments|Discussion|Conclusion|Limitations|Ethics|References|Appendix|A\s+Experimental)', first_500_chars, re.MULTILINE):
            # Extract the matched section
            match = re.search(r'(Introduction|Related Work|Method|Experiments|Discussion|Conclusion|Limitations|Ethics|References|Appendix [A-E]|A\s+Experimental)', first_500_chars)
            if match:
                section = match.group(1)
                if section not in page_info:
                    page_info[section] = page_num + 1

    print("Section starting pages:")
    for section in ['Introduction', 'Related Work', 'Method', 'Experiments', 'Discussion', 'Limitations', 'Ethics', 'References', 'Appendix A']:
        if section in page_info:
            print(f"  {section}: {page_info[section]}")
        elif section == 'Appendix A' and 'A\s+Experimental' in page_info:
            for k in page_info:
                if 'Experimental' in k:
                    print(f"  {k}: {page_info[k]}")

    print(f"\nTotal pages: {len(pdf.pages)}")
